<script setup>
import { onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { api } from '../api'
import { isAdmin } from '@/shared/constants/terminology'
const rows=ref([]),dialog=ref(false),formRef=ref(),submitting=ref(false),form=reactive({name:''}),router=useRouter()
function validateName(_,value,callback){const name=value?.trim()||'';if(!name)callback(new Error('请输入项目名称'));else if(name.length>100)callback(new Error('项目名称最多 100 个字符'));else if(/[\/\\\x00-\x1f]/.test(name))callback(new Error('项目名称不能包含 / 或 \\'));else callback()}
const rules={name:[{validator:validateName,trigger:'blur'}]}
async function load(){rows.value=(await api.get('/objects/projects')).data}
async function create(){if(!(await formRef.value.validate().catch(()=>false)))return;submitting.value=true;try{await api.post('/objects/projects',{name:form.name.trim()});ElMessage.success('测试项目已创建');dialog.value=false;form.name='';await load()}finally{submitting.value=false}}
onMounted(load)
</script>
<template><div class="page"><div class="page-head"><div><h2>测试项目</h2><div class="muted">以原目录结构管理项目文件</div></div><el-button v-if="isAdmin()" type="primary" @click="dialog=true">新建项目</el-button></div><div class="projects"><div v-for="row in rows" :key="row.id" class="project" @click="router.push(`/objects/projects/${row.id}`)"><div class="folder">{{row.name.slice(0,2).toUpperCase()}}</div><div><h3>{{row.name}}</h3><p>最后更新：{{new Date(row.updated_at).toLocaleString()}}</p></div></div><el-empty v-if="!rows.length" description="暂无测试项目"><el-button v-if="isAdmin()" type="primary" @click="dialog=true">新建测试项目</el-button><span v-else class="muted">等待管理员创建测试项目</span></el-empty></div><el-dialog v-model="dialog" title="新建测试项目" width="460" append-to-body><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><el-form-item label="项目名称（创建后不可修改）" prop="name"><el-input v-model="form.name" maxlength="100" placeholder="例如：01gjxt_web 或 登录自动化"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="submitting" @click="create">创建</el-button></template></el-dialog></div></template>
<style scoped>.projects{display:grid;grid-template-columns:repeat(auto-fill,minmax(290px,1fr));gap:16px}.project{position:relative;overflow:hidden;padding:20px;display:flex;align-items:center;gap:16px;border:1px solid var(--border-color);border-radius:14px;background:var(--surface);box-shadow:var(--shadow-soft);cursor:pointer;transition:.25s ease}.project::after{content:"";position:absolute;right:-22px;top:-22px;width:70px;height:70px;border:1px solid var(--primary);border-radius:50%;opacity:.08}.project:hover{transform:translateY(-3px);border-color:var(--border-strong);box-shadow:var(--shadow-card)}.folder{width:52px;height:52px;border:1px solid var(--border-strong);border-radius:12px;color:var(--primary);background:var(--primary-glow);display:grid;place-items:center;font-weight:800;box-shadow:inset 0 0 15px var(--primary-glow)}.project h3{margin:0 0 8px;color:var(--text-primary)}.project p{margin:0;color:var(--text-muted);font-size:13px}</style>
